#' Estimate Phenological Active Duration
#'
#' Calculates the total duration (in calendar days) across simulated posterior
#' probability density curves where activity exceeds a baseline fraction of peak
#' density. Excludes mid-season dormancy (e.g., summer aestivation) and scales
#' automatically by grid step width (`365 / nrow(sim_mat)`) when sub-daily
#' decimal `DOY` grids are supplied.
#'
#' @param sim_mat A numeric matrix (`n_grid x n_sims`, typically `365 x 1000`) of normalized posterior probability density curves generated by [simulate_posterior_density()].
#' @param threshold_fraction Numeric, the activity threshold as a fraction of the curve maximum (default = `0.05`).
#' @return A list containing the posterior `Mean`, `Lower_CI` (2.5%), `Upper_CI` (97.5%) in calendar days, and `Posterior_Draws`.
#' @examples
#' data(sim_carabids)
#' mod <- mgcv::gam(
#'   Count ~ s(DOY, bs = "cc", k = 10) + offset(LogEffort),
#'   family = poisson(), data = sim_carabids,
#'   knots = list(DOY = c(0.5, 365.5))
#' )
#' nd <- create_newdata(mod, doy = "DOY")
#' sim <- simulate_posterior_density(mod, nd, n_sims = 100, warnings = FALSE)
#' estimate_duration(sim)$Mean
#' @export
estimate_duration <- function(sim_mat, threshold_fraction = 0.05) {
  grid <- get_doy_grid(sim_mat)
  res <- apply(sim_mat, 2, function(x) sum(x > (threshold_fraction * max(x))) * grid$dt)
  return(list(
    Mean = mean(res),
    Lower_CI = stats::quantile(res, 0.025),
    Upper_CI = stats::quantile(res, 0.975),
    Posterior_Draws = res
  ))
}
